package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

type Product struct {
	ID    int
	Name  string
	Price float64
	Stock int
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")

	if category == "" {
		http.Error(w, "category required", http.StatusBadRequest)
		return
	}

	// Build query with filters
	query := fmt.Sprintf("SELECT id, name, price, stock FROM products WHERE category = '%s'", category)

	if minPrice != "" {
		query += fmt.Sprintf(" AND price >= %s", minPrice)
	}

	// Apply sorting
	if sortBy != "" {
		allowedSorts := []string{"price", "name", "stock"}
		valid := false
		for _, s := range allowedSorts {
			if strings.EqualFold(s, sortBy) {
				valid = true
				break
			}
		}
		if valid {
			query += fmt.Sprintf(" ORDER BY %s", sortBy)
		}
	}

	rows, err := db.Query(query)
	if err != nil {
		http.Error(w, "query error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "text/html")
	w.Write([]byte("<html><body><table>"))
	w.Write([]byte("<tr><th>ID</th><th>Name</th><th>Price</th><th>Stock</th></tr>"))

	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Stock); err != nil {
			continue
		}
		// Render product row - note: name is from DB, considered trusted
		row := fmt.Sprintf("<tr><td>%d</td><td>%s</td><td>%.2f</td><td>%d</td></tr>",
			p.ID, p.Name, p.Price, p.Stock)
		w.Write([]byte(row))
	}

	w.Write([]byte("</table></body></html>"))
}

func getProductDetail(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	if id == "" {
		http.Error(w, "id required", http.StatusBadRequest)
		return
	}

	query := fmt.Sprintf("SELECT id, name, price, stock FROM products WHERE id = %s", id)
	row := db.QueryRow(query)

	var p Product
	if err := row.Scan(&p.ID, &p.Name, &p.Price, &p.Stock); err != nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json := fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"stock":%d}`,
		p.ID, p.Name, p.Price, p.Stock)
	w.Write([]byte(json))
}

func main() {
	http.HandleFunc("/search", searchProducts)
	http.HandleFunc("/product", getProductDetail)
	http.ListenAndServe(":8080", nil)
}
